// Parse Snyk JSON output in TypeScript
import { execSync } from 'child_process';

interface SnykVulnerability {
  id: string;
  title: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  packageName: string;
  version: string;
  fixedIn: string[];
}

interface SnykResult {
  ok: boolean;
  vulnerabilities: SnykVulnerability[];
  dependencyCount: number;
}

function runSnykTest(projectPath: string): SnykResult {
  const output = execSync(`snyk test --json`, {
    cwd: projectPath,
    env: { ...process.env, SNYK_TOKEN: process.env.SNYK_TOKEN },
  }).toString();
  return JSON.parse(output) as SnykResult;
}

import { execSync, ExecSyncOptionsWithStringEncoding } from 'child_process';

interface SnykVuln {
  id: string;
  title: string;
  severity: string;
  packageName: string;
  version: string;
  fixedIn: string[];
  isUpgradable: boolean;
  isPatchable: boolean;
}

interface SnykReport {
  ok: boolean;
  vulnerabilities: SnykVuln[];
  dependencyCount: number;
  summary: string;
}

function auditDependencies(cwd: string): SnykReport {
  const opts: ExecSyncOptionsWithStringEncoding = {
    cwd,
    encoding: 'utf8',
    env: { ...process.env },
    // snyk test exits 1 on findings — don't throw, capture output
    stdio: ['pipe', 'pipe', 'pipe'],
  };

  let raw: string;
  try {
    raw = execSync('snyk test --json', opts);
  } catch (err: unknown) {
    // Exit code 1 means vulnerabilities found — stdout still has JSON
    const execError = err as { stdout?: string };
    raw = execError.stdout ?? '{}';
  }

  const report = JSON.parse(raw) as SnykReport;

  const highs = report.vulnerabilities.filter(
    (v) => v.severity === 'high' || v.severity === 'critical'
  );

  if (highs.length > 0) {
    console.error(`Found ${highs.length} high/critical vulnerabilities:`);
    for (const v of highs) {
      console.error(`  [${v.severity.toUpperCase()}] ${v.title} in ${v.packageName}@${v.version}`);
    }
  }

  return report;
}
